LIB.push(
{t:"Ikigai: ragioni per vivere",c:"app",tg:"Cerca il punto in cui si incontrano ciò che ami, ciò in cui sei bravo, ciò che serve e ciò per cui vieni pagato.",d:2,
sp:"Ikigai è una parola giapponese che significa più o meno «ragione per vivere». In Occidente è diventata famosa con un diagramma di quattro cerchi: ciò che ami, ciò in cui sei bravo, ciò di cui il mondo ha bisogno e ciò per cui puoi essere pagato. Il punto in cui si incontrano tutti e quattro sarebbe il tuo ikigai. Nella cultura giapponese però il termine indica anche piccole gioie quotidiane, non solo il lavoro.",
ap:["Il diagramma a quattro cerchi è un'aggiunta occidentale, ma è uno strumento utile per riflettere: mostra cosa manca quando una cosa ti piace ma non ti mantiene, o ti mantiene ma non ti appassiona. Il ricercatore Ken Mogi ricorda che l'ikigai giapponese è fatto anche di cose semplici: il caffè del mattino, curare un orto, vedere crescere i nipoti.","Usalo senza pressione: non serve trovare una missione perfetta. Puoi avere più ikigai, e possono cambiare con l'età. Cerca di aumentare le attività che toccano più cerchi e di notare le piccole ragioni quotidiane che ti fanno alzare volentieri."],
ri:[["Lavoro senza senso","Ti paga ma non ti dice nulla."],["Passione che non mantiene","Ami qualcosa ma non riesci a viverne."],["Mattine senza motivazione","Non trovi un motivo per alzarti volentieri."]],
es:[["Lavoro","Un contabile ama insegnare. Inizia a tenere corsi di educazione finanziaria serali: unisce competenza, passione e un bisogno reale."],["Te stesso","Una pensionata scopre il suo ikigai nel curare l'orto del quartiere e regalare la verdura ai vicini."]],
ex:["Disegna i quattro cerchi e scrivi almeno tre voci in ciascuno.","Cerca le voci che compaiono in più cerchi.","Scrivi cinque piccole gioie quotidiane che ti danno una ragione per alzarti."],
q:["Cosa amo, in cosa sono bravo, cosa serve, per cosa vengo pagato?","Quali attività toccano più cerchi insieme?","Quali piccole gioie quotidiane mi danno senso?"],
er:"Sentirsi in colpa per non aver trovato una missione perfetta e unica.",
qz:[["Quali sono i quattro cerchi del diagramma occidentale dell'ikigai?",["Salute, soldi, amore, lavoro","Ciò che ami, ciò in cui sei bravo, ciò che serve, ciò per cui sei pagato","Passato, presente, futuro, sogno","Famiglia, amici, lavoro, hobby"],1,"Il punto di incontro sarebbe l'ikigai."],["Cosa ricorda Ken Mogi sull'ikigai giapponese?",["È solo il lavoro","Comprende anche piccole gioie quotidiane","Serve solo agli anziani","È un'azienda"],1,"Non è solo una missione professionale."]]},

{t:"La matrice impatto-sforzo",c:"lav",tg:"Scegli prima ciò che dà molto risultato con poco sforzo.",d:1,
sp:"Quando hai molte idee o compiti, mettili in una griglia con due assi: impatto (quanto risultato danno) e sforzo (quanto costano). Ne escono quattro gruppi: vittorie rapide (alto impatto, poco sforzo) da fare subito; grandi progetti (alto impatto, molto sforzo) da pianificare; riempitivi (basso impatto, poco sforzo) da fare se resta tempo; trappole (basso impatto, molto sforzo) da evitare.",
ap:["La matrice è semplice ma potente perché obbliga a stimare due cose che di solito confondiamo: quanto ci piace un'idea e quanto rende davvero. Spesso scopriamo di essere impegnati in trappole che sembravano importanti.","Le stime sono approssimative: conviene farle in gruppo e confrontarle. Attenzione a non riempire la giornata solo di vittorie rapide: i grandi progetti richiedono sforzo ma spesso cambiano davvero le cose."],
ri:[["Troppe idee","Non sai da quale partire."],["Molto lavoro, pochi risultati","Ti impegni in attività che rendono poco."],["Liste infinite","Ogni compito sembra ugualmente importante."]],
es:[["Casa","Per rendere la casa più accogliente: cambiare le lampadine con luce calda è una vittoria rapida, rifare il pavimento è un grande progetto, ridipingere la cantina è una trappola."],["Lavoro","Il gruppo vota 15 idee per migliorare il servizio clienti. Ne realizza subito tre ad alto impatto e basso sforzo."]],
ex:["Elenca dieci attività o idee e posizionale nella griglia.","Fai questa settimana una vittoria rapida.","Individua una trappola su cui stai spendendo energia e abbandonala."],
q:["Quanto risultato darà questa attività?","Quanto mi costerà?","Sto cadendo in una trappola che sembra importante?"],
er:"Fare solo vittorie rapide e rimandare per sempre i grandi progetti.",
qz:[["Cosa fare con un'attività ad alto impatto e basso sforzo?",["Evitarla","Farla subito","Rimandarla","Delegarla sempre"],1,"È una vittoria rapida."],["Come si chiamano le attività a basso impatto e alto sforzo?",["Vittorie rapide","Trappole da evitare","Grandi progetti","Riempitivi"],1,"Consumano energia senza risultati."]]},

{t:"L'invidia come mappa",c:"app",tg:"Ciò che invidi negli altri ti indica ciò che desideri davvero.",d:2,
sp:"L'invidia è un'emozione scomoda e spesso nascosta. Ma può essere utile: se la osservi con attenzione, ti mostra cosa desideri per te. Non invidiamo tutto ciò che hanno gli altri, solo alcune cose precise. Il modello ti invita a trasformare l'invidia da veleno a mappa, chiedendoti cosa ti indica e cosa puoi fare per avvicinarti.",
ap:["Puoi invidiare il successo di un collega, i viaggi di un amico, la calma di un vicino. Spesso però non vuoi tutta la loro vita, ma un aspetto preciso: la libertà, il riconoscimento, il tempo. Distinguere questo aspetto è la parte importante dell'esercizio.","Usata così, l'invidia diventa un'informazione. Chiediti: cosa esattamente invidio? Sarei disposto a pagare il prezzo che ha pagato lui? Quale piccolo passo posso fare verso quella cosa? Se la risposta è no, l'invidia perde forza."],
ri:[["Fastidio per il successo altrui","Le buone notizie di qualcuno ti irritano."],["Confronto sui social","Ti senti peggio dopo aver visto le vite degli altri."],["Desideri non detti","Non sai bene cosa vuoi, ma sai cosa ti punge."]],
es:[["Lavoro","Provi invidia per una collega che ha iniziato a insegnare corsi. Capisci che desideri condividere ciò che sai e proponi un incontro di formazione interno."],["Te stesso","Invidi un amico che vive in campagna. Scopri che ciò che vuoi è più tempo all'aperto: inizi a passare le domeniche in montagna."]],
ex:["Scrivi tre persone che invidi e, per ciascuna, l'aspetto preciso che ti punge.","Chiediti se saresti disposto a pagare il prezzo che quelle persone hanno pagato.","Scegli un piccolo passo concreto verso uno di quei desideri."],
q:["Cosa esattamente invidio?","Vorrei davvero la sua vita, o solo un aspetto?","Quale passo posso fare io in quella direzione?"],
er:"Restare nel rancore invece di usare l'invidia come informazione.",
qz:[["Cosa suggerisce il modello sull'invidia?",["Va sempre repressa","Può indicare ciò che desideri davvero","Va sfogata","È sempre negativa"],1,"Osservata con attenzione, diventa una mappa."],["Quale domanda aiuta a ridurre l'invidia?",["Perché lui sì e io no?","Sarei disposto a pagare il prezzo che ha pagato?","Come posso criticarlo?","Chi ha più successo?"],1,"Spesso non vorremmo davvero il prezzo."]]},

{t:"Jobs To Be Done",c:"lav",tg:"Le persone «assumono» un prodotto per fare un lavoro nella loro vita.",d:2,
sp:"Clayton Christensen proponeva di chiedersi non chi è il cliente, ma quale «lavoro» il cliente vuole portare a termine. Le persone non comprano un trapano: vogliono un buco nel muro, o meglio ancora un quadro appeso. Capire il lavoro da svolgere aiuta a creare prodotti utili e a capire perché le persone scelgono una soluzione invece di un'altra.",
ap:["Un esempio famoso riguarda un frullato venduto la mattina. Molti lo compravano per un lavoro preciso: avere qualcosa che tenesse occupati e sazi durante un lungo viaggio in auto verso l'ufficio. I veri concorrenti non erano altri frullati, ma banane, ciambelle e la radio.","Ogni lavoro ha aspetti funzionali (cosa deve fare), emotivi (come voglio sentirmi) e sociali (come voglio apparire). Chiedersi «per quale lavoro le persone assumono questo?» apre idee nuove e mostra concorrenti inattesi."],
ri:[["Clienti che scelgono cose diverse","Non capisci perché preferiscono un'alternativa."],["Prodotti con troppe funzioni","Si aggiungono caratteristiche che nessuno usa."],["Concorrenza vista troppo stretta","Guardi solo chi fa la tua stessa cosa."]],
es:[["Lavoro","Una libreria scopre che molti clienti «assumono» il negozio per trovare un regalo in fretta. Crea uno scaffale «regali pronti» con pacchetto incluso."],["Te stesso","Ti chiedi per quale lavoro «assumi» i social la sera: rilassarti. Trovi un modo migliore per farlo: leggere o fare una passeggiata."]],
ex:["Scegli un prodotto che usi spesso e scrivi il lavoro funzionale, emotivo e sociale per cui lo usi.","Per qualcosa che offri, chiedi a tre persone perché l'hanno scelto e cosa usavano prima.","Elenca i concorrenti inattesi che svolgono lo stesso lavoro."],
q:["Quale lavoro vuole portare a termine questa persona?","Come vuole sentirsi e apparire?","Cos'altro potrebbe «assumere» per lo stesso lavoro?"],
er:"Descrivere il lavoro in modo troppo vago, come «essere felice».",
qz:[["Cosa significa «Jobs To Be Done»?",["Le mansioni di un dipendente","Il lavoro che una persona vuole portare a termine scegliendo un prodotto","Un elenco di compiti","Un tipo di contratto"],1,"Si «assume» un prodotto per un compito."],["Nel caso del frullato mattutino, chi erano i veri concorrenti?",["Altri frullati","Banane, ciambelle e la radio","Nessuno","I bar"],1,"Svolgevano lo stesso lavoro durante il viaggio."]]},

{t:"La mappa del percorso",c:"lav",tg:"Disegna ogni passo dell'esperienza di una persona per vedere dove si inceppa.",d:1,
sp:"La mappa del percorso del cliente descrive, passo dopo passo, l'esperienza di una persona con un servizio: da quando scopre di avere un bisogno a quando lo risolve, e anche dopo. Per ogni passo si annotano cosa fa, cosa pensa, cosa prova e dove incontra difficoltà. Serve a vedere il servizio con gli occhi di chi lo usa.",
ap:["Spesso un'organizzazione guarda il proprio servizio a pezzi, reparto per reparto. Il cliente invece vive un percorso unico, e un problema in un punto rovina tutta l'esperienza. La mappa rende visibili i momenti di frustrazione e quelli che possono diventare memorabili.","Si può usare anche fuori dal lavoro: il percorso di un ospite che arriva a una festa, di un paziente in un ambulatorio, di un nuovo collega nel suo primo giorno. Basta seguire davvero una persona reale invece di immaginare."],
ri:[["Lamentele sparse","I problemi sembrano casuali ma si ripetono."],["Reparti che non si parlano","Ognuno vede solo il suo pezzo."],["Primi giorni difficili","Chi arriva si sente perso."]],
es:[["Lavoro","Un dentista disegna il percorso del paziente: prenotazione difficile, attesa senza informazioni, pagamento lento. Introduce un messaggio con l'orario aggiornato."],["Famiglia","Prima di ospitare dei parenti, immagini il loro percorso dall'arrivo in stazione alla camera. Prepari indicazioni e asciugamani in vista."]],
ex:["Scegli un servizio che offri o usi e disegna almeno otto passi del percorso.","Per ogni passo, segna con un simbolo se l'esperienza è positiva, neutra o frustrante.","Migliora il passo più frustrante con un'azione concreta."],
q:["Quali sono tutti i passi che vive questa persona?","Dove si sente persa o frustrata?","Quale momento potrebbe diventare memorabile?"],
er:"Disegnare il percorso ideale invece di quello reale.",
qz:[["Cosa descrive la mappa del percorso del cliente?",["L'organigramma","Ogni passo dell'esperienza di una persona con un servizio","Il bilancio","La strada per il negozio"],1,"Mostra il servizio dal punto di vista di chi lo usa."],["Perché è utile?",["Mostra solo i costi","Rende visibili i punti di frustrazione lungo tutto il percorso","Sostituisce il personale","Elimina i reparti"],1,"Un problema in un punto rovina l'insieme."]]},

{t:"Kanban: rendere visibile il lavoro",c:"lav",tg:"Metti i compiti su una lavagna in colonne e limita quanti ne fai insieme.",d:1,
sp:"Kanban significa «cartellino» in giapponese e nasce nelle fabbriche Toyota. Oggi indica una lavagna divisa in colonne, come «da fare», «in corso» e «fatto», dove ogni compito è un cartellino che si sposta. La regola chiave è limitare quanti compiti possono stare «in corso» nello stesso momento: finire conta più che iniziare.",
ap:["Rendere visibile il lavoro mostra subito dove si accumula e dove c'è un collo di bottiglia. Limitare il lavoro in corso riduce il passaggio continuo tra attività e fa finire le cose più in fretta. Si dice: «smetti di iniziare, inizia a finire».","Funziona per un ufficio, una famiglia o da soli: bastano tre colonne su un foglio o una porta con dei foglietti adesivi. Il limite iniziale può essere di tre compiti in corso a persona."],
ri:[["Troppe cose iniziate","Molti lavori a metà, pochi finiti."],["Nessuno sa chi fa cosa","Il lavoro è invisibile."],["Code nascoste","Compiti che aspettano senza che nessuno lo noti."]],
es:[["Casa","Sul frigorifero tre colonne con i lavori di casa. Ognuno sposta i foglietti. Finiscono le discussioni su chi ha fatto cosa."],["Lavoro","Un piccolo gruppo limita a due i compiti in corso per persona. I tempi di consegna si dimezzano."]],
ex:["Crea una lavagna con tre colonne per i tuoi compiti di questa settimana.","Fissa un limite massimo di tre compiti «in corso».","Alla fine della settimana osserva dove si sono accumulati i cartellini."],
q:["Quanti compiti ho in corso in questo momento?","Dove si accumula il lavoro?","Cosa posso finire prima di iniziare altro?"],
er:"Usare la lavagna senza limitare il lavoro in corso.",
qz:[["Qual è la regola chiave del Kanban?",["Iniziare più compiti possibile","Limitare il numero di compiti in corso","Lavorare di notte","Non scrivere nulla"],1,"Finire conta più che iniziare."],["Cosa mostra una lavagna Kanban?",["Solo i compiti finiti","Dove si accumula il lavoro e i colli di bottiglia","Gli stipendi","Le vacanze"],1,"Rendere visibile il lavoro rivela i problemi."]]},

{t:"Il modello Kano",c:"lav",tg:"Distingui ciò che è dato per scontato, ciò che più ce n'è meglio è, e ciò che entusiasma.",d:2,
sp:"Noriaki Kano ha classificato le caratteristiche di un prodotto o servizio in tre tipi principali. Requisiti di base: se mancano, i clienti sono scontenti, ma se ci sono nessuno li nota (un albergo pulito). Prestazioni: più ce ne sono, più i clienti sono contenti (wifi più veloce). Elementi entusiasmanti: inattesi, creano piacere ma la loro assenza non delude (un biglietto di benvenuto).",
ap:["Il modello spiega perché aggiungere funzioni non basta: se i requisiti di base mancano, nessun elemento entusiasmante salva l'esperienza. Inoltre, con il tempo, ciò che entusiasmava diventa normale e poi di base: la fotocamera nel telefono una volta stupiva, oggi è scontata.","Per usarlo: prima assicurati che le basi siano perfette, poi lavora sulle prestazioni importanti, infine aggiungi qualche sorpresa. Vale anche nelle relazioni: puntualità e rispetto sono di base, un gesto inatteso entusiasma."],
ri:[["Lamentele su cose banali","Mancano i requisiti di base."],["Funzioni che nessuno nota","Hai investito in cose date per scontate."],["Sorprese che diventano abitudini","Ciò che stupiva ora è normale."]],
es:[["Lavoro","Un ristorante cura il servizio impeccabile (base), migliora la velocità (prestazione) e offre un piccolo assaggio della casa (entusiasmo)."],["Relazioni","Ricordarsi il compleanno è una base; organizzare una sorpresa per qualcosa che l'altro aveva nominato mesi prima entusiasma."]],
ex:["Per un servizio che offri, scrivi due requisiti di base, due prestazioni e un elemento entusiasmante.","Controlla che tutti i requisiti di base siano rispettati prima di aggiungere altro.","Fai un piccolo gesto inatteso per qualcuno questa settimana."],
q:["Le basi sono perfette?","Quali prestazioni contano di più per chi lo usa?","Quale piccola sorpresa potrebbe entusiasmare?"],
er:"Cercare di entusiasmare quando mancano ancora le basi.",
qz:[["Cosa succede se manca un requisito di base?",["Nessuno se ne accorge","I clienti sono scontenti","I clienti sono entusiasti","Le vendite aumentano"],1,"Le basi si notano solo quando mancano."],["Cosa succede agli elementi entusiasmanti nel tempo?",["Restano sempre sorprendenti","Tendono a diventare normali e poi di base","Spariscono","Diventano costosi"],1,"Le aspettative crescono."]]},

{t:"Kintsugi: il valore della riparazione",c:"app",tg:"Le rotture riparate con cura possono rendere un oggetto, o una persona, più prezioso.",d:1,
sp:"Il kintsugi è un'arte giapponese che ripara le ceramiche rotte con lacca mescolata a polvere d'oro. Le crepe non vengono nascoste, ma messe in evidenza: diventano parte della storia dell'oggetto e lo rendono unico. Come modello mentale, il kintsugi invita a guardare errori, ferite e fallimenti come parti preziose della propria storia.",
ap:["Viviamo spesso cercando di nascondere ciò che si è rotto: un fallimento, un divorzio, un periodo difficile. Il kintsugi suggerisce un'altra strada: riparare con cura e mostrare con onestà il percorso fatto. Le persone che sanno raccontare le proprie cicatrici spesso ispirano fiducia.","Questo non significa cercare le rotture o fingere che il dolore sia bello. Significa che la riparazione richiede tempo e cura, e che ciò che è stato riparato può avere un valore diverso, e a volte maggiore, di prima."],
ri:[["Vergogna per un fallimento","Nascondi una parte della tua storia."],["Desiderio di tornare come prima","Cerchi di cancellare ciò che è successo."],["Oggetti o relazioni rotti","Pensi di dover buttare tutto."]],
es:[["Te stesso","Dopo un periodo di depressione, una persona inizia a raccontarlo agli amici. Scopre che la sua esperienza aiuta altri a chiedere aiuto."],["Relazioni","Dopo una grossa lite, due amici si chiariscono con sincerità. Il rapporto diventa più profondo di prima."]],
ex:["Scrivi un tuo fallimento o una ferita passata e cosa ti ha insegnato.","Ripara qualcosa di rotto in casa invece di buttarlo.","Pensa a una relazione incrinata e a un piccolo gesto per ripararla."],
q:["Cosa ho imparato da questa rottura?","Come posso ripararla con cura invece di nasconderla?","Questa cicatrice può aiutare qualcun altro?"],
er:"Usare il kintsugi per giustificare il non affrontare un problema.",
qz:[["Cosa fa il kintsugi con le crepe di una ceramica?",["Le nasconde","Le mette in evidenza con l'oro","Le lascia aperte","Butta l'oggetto"],1,"Le crepe diventano parte del valore."],["Come si applica il kintsugi alla vita?",["Nascondere i fallimenti","Riparare con cura e valorizzare la propria storia","Evitare ogni rischio","Ricominciare da zero sempre"],1,"Le ferite riparate fanno parte di chi siamo."]]},

{t:"Lean Startup",c:"lav",tg:"Costruisci poco, misura le reazioni, impara e decidi se continuare o cambiare.",d:2,
sp:"Eric Ries ha descritto un metodo per avviare progetti nuovi in condizioni di incertezza. Invece di scrivere un piano perfetto e lavorare per anni in segreto, si segue un ciclo: costruisci una versione minima, misura come reagiscono le persone, impara cosa funziona. Poi decidi se continuare o cambiare direzione, il cosiddetto pivot.",
ap:["Molti progetti falliscono non perché sono fatti male, ma perché nessuno ne ha bisogno. Il metodo Lean Startup cerca di scoprirlo il prima possibile spendendo poco. Ogni idea viene trattata come un'ipotesi da verificare con dati reali, non con opinioni.","Puoi applicarlo a qualsiasi iniziativa nuova: un corso, un negozio online, un'associazione. La domanda chiave è: qual è il modo più economico e veloce per scoprire se ho ragione?"],
ri:[["Progetti lunghi senza clienti","Lavori mesi prima di mostrare qualcosa."],["Idee basate su opinioni","Gli amici dicono che è bello."],["Paura di cambiare direzione","Continui anche se i dati dicono di no."]],
es:[["Lavoro","Prima di aprire un servizio di pasti a domicilio, una cuoca prepara 20 pranzi a settimana per i colleghi per un mese. Scopre cosa piace e quanto sono disposti a pagare."],["Te stesso","Prima di comprare tutta l'attrezzatura per la fotografia, noleggi una macchina per un weekend."]],
ex:["Scrivi l'ipotesi principale della tua idea in una frase.","Progetta un test che costi meno di 50 euro e duri meno di due settimane.","Fissa in anticipo quale risultato ti farà continuare e quale cambiare."],
q:["Quale ipotesi devo verificare per prima?","Qual è il modo più economico per scoprirlo?","Cosa mi dicono i dati: continuo o cambio?"],
er:"Confondere «minimo» con «fatto male»: la versione minima deve comunque essere utile.",
qz:[["Qual è il ciclo del Lean Startup?",["Pianifica, costruisci, vendi","Costruisci, misura, impara","Investi, assumi, cresci","Pensa, aspetta, decidi"],1,"Il ciclo si ripete per ridurre l'incertezza."],["Cos'è un pivot?",["Un errore","Un cambio di direzione basato su ciò che si è imparato","Una vendita","Un investimento"],1,"Si cambia strategia senza buttare tutto."]]},

{t:"Pensiero snello",c:"lav",tg:"Elimina gli sprechi e fai scorrere il lavoro verso ciò che ha valore per chi lo riceve.",d:2,
sp:"Il pensiero snello, o lean, nasce dal sistema di produzione Toyota. L'idea è semplice: definire cosa ha valore per il cliente, eliminare tutto ciò che non aggiunge valore (gli sprechi) e far scorrere il lavoro senza interruzioni. Tra gli sprechi classici ci sono attese, spostamenti inutili, errori, scorte eccessive e lavoro in più che nessuno ha chiesto.",
ap:["Un principio chiave è il miglioramento continuo: piccoli passi ogni giorno fatti da chi fa il lavoro, non solo dai capi. Un altro è produrre solo ciò che serve quando serve, invece di accumulare. Molti sprechi diventano visibili solo seguendo un processo dall'inizio alla fine.","Puoi applicarlo alla casa (riorganizzare la cucina per fare meno passi), all'ufficio (togliere approvazioni inutili), allo studio. Attenzione a non confondere snello con tagliare persone: lo scopo è eliminare lo spreco, non il valore."],
ri:[["Attese","Persone o pratiche ferme in coda."],["Lavoro rifatto","Errori che costringono a ripetere."],["Scorte e accumuli","Cose comprate o prodotte in eccesso."]],
es:[["Casa","Osservi quanti passi fai per preparare la colazione. Spostando tazze, caffè e pane vicino alla macchinetta, risparmi tempo ogni mattina."],["Lavoro","Un ufficio scopre che ogni rimborso spese passa da cinque firme. Ne bastano due."]],
ex:["Segui un tuo processo quotidiano e annota ogni attesa, spostamento o ripetizione.","Elimina uno spreco evidente questa settimana.","Chiediti cosa ha valore per la persona che riceve il tuo lavoro."],
q:["Cosa ha davvero valore per chi riceve il lavoro?","Quali passaggi non aggiungono valore?","Dove il lavoro si ferma o si accumula?"],
er:"Tagliare ciò che sembra inutile ma in realtà protegge qualità o sicurezza.",
qz:[["Qual è l'obiettivo del pensiero snello?",["Lavorare di più","Eliminare gli sprechi e far scorrere ciò che ha valore","Ridurre il personale","Comprare più macchine"],1,"Si concentra sul valore per il cliente."],["Quale è uno spreco classico?",["Un servizio richiesto dal cliente","Attese e lavoro rifatto per errori","La formazione","La pausa pranzo"],1,"Non aggiungono valore."]]},

{t:"Il sistema Leitner",c:"app",tg:"Ripassa più spesso ciò che sbagli e meno spesso ciò che sai già.",d:1,
sp:"Il giornalista Sebastian Leitner ha inventato negli anni Settanta un metodo semplice per memorizzare con le schede. Si usano diverse scatole: le schede nuove stanno nella prima, che si ripassa ogni giorno. Se rispondi bene, la scheda passa alla scatola successiva, ripassata meno spesso. Se sbagli, torna nella prima. Così concentri il tempo su ciò che non sai.",
ap:["Il metodo applica la ripetizione dilazionata: ripassare a intervalli crescenti aiuta il ricordo a durare. Funziona per lingue, date, formule, nomi, termini tecnici. Molte app di flashcard usano lo stesso principio in modo automatico.","Per partire bastano cartoncini e tre o cinque scatole, ad esempio ripassate ogni giorno, ogni tre giorni e ogni settimana. La regola importante è essere onesti: se la risposta è stata incerta, la scheda torna indietro."],
ri:[["Ripassi tutto allo stesso modo","Perdi tempo su ciò che sai già."],["Dimentichi dopo l'esame","Hai studiato tutto all'ultimo."],["Tante cose da memorizzare","Parole, formule, nomi."]],
es:[["Studio","Per imparare 500 parole di inglese, usi cinque scatole. Dopo un mese ripassi ogni giorno solo una trentina di schede difficili."],["Lavoro","Un nuovo infermiere memorizza dosi e nomi di farmaci con il sistema Leitner sul telefono."]],
ex:["Crea dieci schede su qualcosa che vuoi imparare e mettile in tre scatole.","Ripassa per una settimana la prima scatola ogni giorno, spostando le schede.","Prova un'app di flashcard con ripetizione dilazionata."],
q:["Cosa so già e cosa sbaglio ancora?","Sto dedicando il tempo alle schede difficili?","Sono onesto quando una risposta è incerta?"],
er:"Spostare avanti le schede anche quando la risposta era incerta.",
qz:[["Cosa succede a una scheda sbagliata nel sistema Leitner?",["Passa alla scatola successiva","Torna nella prima scatola","Viene buttata","Resta dove è"],1,"Ciò che sbagli si ripassa più spesso."],["Su quale principio si basa il sistema?",["Ripasso di massa la sera prima","Ripetizione dilazionata","Lettura veloce","Nessuno"],1,"Gli intervalli crescenti rafforzano il ricordo."]]},

{t:"L'effetto lock-in",c:"eco",tg:"Più investi in una scelta, più diventa costoso cambiarla.",d:2,
sp:"Il lock-in, o effetto blocco, si verifica quando cambiare fornitore, tecnologia o abitudine diventa così costoso che restiamo con la scelta attuale anche se ne esistono di migliori. I costi di cambiamento possono essere soldi, tempo per imparare, dati da trasferire, accessori incompatibili o relazioni da ricostruire.",
ap:["Molte aziende progettano apposta il lock-in: ecosistemi in cui i dispositivi funzionano bene solo tra loro, programmi fedeltà, formati di file chiusi. Un esempio storico è la tastiera QWERTY: non è la più efficiente, ma tutti l'hanno imparata e cambiarla costerebbe troppo.","Prima di una scelta importante chiediti: quanto mi costerà cambiare in futuro? Preferisci opzioni aperte quando l'incertezza è alta. E quando sei già bloccato, calcola onestamente il costo di restare rispetto a quello di cambiare."],
ri:[["«Ormai ci sono dentro»","Resti perché cambiare costa troppo."],["Accessori incompatibili","Ciò che hai comprato funziona solo con un marchio."],["Dati intrappolati","Non puoi esportare facilmente le tue informazioni."]],
es:[["Acquisti","Tutte le tue foto sono in un servizio che non permette di scaricarle facilmente. Prima che diventino troppe, ne fai una copia altrove."],["Lavoro","Un'azienda sceglie un software che salva i dati in un formato standard, così potrà cambiare fornitore in futuro."]],
ex:["Elenca tre servizi o prodotti da cui ti senti bloccato e il costo di cambiare.","Per un servizio importante, verifica come esportare i tuoi dati.","Prima del prossimo acquisto importante, chiediti quanto costerà cambiare tra cinque anni."],
q:["Quanto mi costerà cambiare in futuro?","Resto per scelta o perché sono bloccato?","Esiste un'opzione più aperta?"],
er:"Ignorare i costi di cambiamento al momento della prima scelta.",
qz:[["Cos'è il lock-in?",["Una serratura","Una situazione in cui cambiare scelta diventa troppo costoso","Un tipo di contratto","Un'offerta speciale"],1,"I costi di cambiamento ci tengono bloccati."],["Come ridurre il rischio di lock-in?",["Scegliere sempre il più economico","Preferire opzioni aperte e verificare come esportare i dati","Non cambiare mai","Comprare tutto dallo stesso marchio"],1,"Mantiene possibile il cambiamento."]]},

{t:"Avversione alla perdita",c:"rag",tg:"Il dolore di perdere qualcosa pesa più del piacere di guadagnare la stessa cosa.",d:2,
sp:"Daniel Kahneman e Amos Tversky hanno mostrato che una perdita pesa psicologicamente circa il doppio di un guadagno equivalente. Perdere 100 euro fa più male di quanto ne faccia piacere trovarne 100. Questa asimmetria ci rende prudenti, ma ci fa anche rifiutare scommesse vantaggiose, tenere investimenti in perdita e restare in situazioni insoddisfacenti.",
ap:["L'avversione alla perdita spiega molti comportamenti: non vendiamo un'azione in calo per non «rendere reale» la perdita, accettiamo garanzie costose, temiamo il cambiamento perché vediamo soprattutto cosa perderemmo. Chi vende lo sa: «non perdere questa occasione» funziona meglio di «approfitta di questa occasione».","Per contrastarla, riformula le scelte guardando il risultato complessivo nel tempo, non la singola perdita. Chiediti: se partissi da zero, sceglierei questa situazione? E ricorda che anche non agire ha dei costi."],
ri:[["Paura del cambiamento","Vedi solo cosa perderesti."],["Tenere ciò che va male","Non vendi, non lasci, non chiudi."],["Messaggi «non perdere»","Ti spingono a decidere per paura."]],
es:[["Soldi","Un'azione ha perso il 30%. Non la vendi «per non perdere». Ti chiedi: la comprerei oggi? No. La vendi e investi altrove."],["Lavoro","Ti offrono un lavoro migliore ma pensi a ciò che lasceresti. Scrivi anche cosa perdi restando: crescita e stipendio."]],
ex:["Per una decisione bloccata, scrivi cosa perdi cambiando e cosa perdi restando.","Nota tre messaggi pubblicitari che usano la paura di perdere.","Per un investimento o un impegno in perdita, chiediti: lo sceglierei oggi da zero?"],
q:["Sto evitando una perdita o cercando il risultato migliore?","Cosa perdo restando fermo?","Se partissi da zero, sceglierei questa situazione?"],
er:"Credere che evitare ogni perdita significhi decidere bene.",
qz:[["Cosa dice l'avversione alla perdita?",["Guadagni e perdite pesano uguale","Una perdita pesa più di un guadagno equivalente","Le perdite non contano","Preferiamo rischiare"],1,"Il dolore di perdere è circa doppio."],["Perché «non perdere questa offerta» funziona?",["È più corto","Sfrutta la paura di perdere","È più gentile","Non funziona"],1,"La paura della perdita spinge all'azione."]]},

{t:"I modelli mentali",c:"rag",tg:"Rappresentazioni semplificate di come funziona il mondo, da usare come strumenti per pensare.",d:1,
sp:"Un modello mentale è una spiegazione semplificata di come funziona qualcosa: la domanda e l'offerta, l'inerzia, il pensiero di secondo ordine. Tutti usiamo modelli mentali, spesso senza saperlo. Questa app esiste perché conoscerne molti, da campi diversi, permette di vedere i problemi da più angolazioni e di prendere decisioni migliori.",
ap:["Ogni modello è come una lente: mostra alcune cose e ne nasconde altre. Chi conosce un solo modello tende a usarlo per tutto, come chi ha solo un martello e vede chiodi ovunque. Avere una cassetta degli attrezzi varia permette di scegliere lo strumento giusto per ogni situazione.","I modelli servono solo se li usi. Imparare la definizione non basta: bisogna riconoscerli nella vita reale e applicarli alle proprie decisioni, come fai con gli esercizi e le schede di questa app. E ricorda che sono semplificazioni: la mappa non è il territorio."],
ri:[["Sempre la stessa spiegazione","Interpreti tutto con un'unica idea."],["Decisioni prese d'abitudine","Non sai bene perché scegli così."],["Problemi visti da un solo lato","Ti manca un'altra prospettiva."]],
es:[["Lavoro","Davanti a un calo di vendite, una manager usa tre modelli: colli di bottiglia, incentivi e domanda e offerta. Ognuno suggerisce una causa diversa da verificare."],["Te stesso","Per decidere se cambiare città usi l'inversione, il pensiero di secondo ordine e il costo opportunità. La scelta diventa più chiara."]],
ex:["Scegli un problema attuale e applica tre modelli diversi che hai studiato. Cosa ti mostra ciascuno?","Scrivi i cinque modelli che usi più spesso e uno che vuoi usare di più.","Ogni sera per una settimana annota un modello che hai visto in azione durante il giorno."],
q:["Quale modello sto usando, anche senza saperlo?","Quale altro modello mi farebbe vedere il problema diversamente?","Questo modello si adatta davvero alla situazione?"],
er:"Collezionare modelli senza mai applicarli.",
qz:[["Cos'è un modello mentale?",["Una persona da imitare","Una rappresentazione semplificata di come funziona qualcosa","Un test psicologico","Una regola fissa"],1,"È uno strumento per pensare."],["Perché conviene conoscere molti modelli?",["Per impressionare gli altri","Per guardare i problemi da più angolazioni e scegliere lo strumento giusto","Perché uno solo è sbagliato","Non conviene"],1,"Ogni modello mostra qualcosa di diverso."]]},

{t:"Il metodo dei loci",c:"app",tg:"Ricorda una lista immaginando di disporre gli elementi lungo un percorso che conosci bene.",d:1,
sp:"Il metodo dei loci, o palazzo della memoria, risale all'antica Grecia. Si sceglie un luogo che conosci benissimo, come la tua casa, e si immagina di camminarci dentro, lasciando in ogni punto (porta, divano, cucina) un'immagine vivida dell'elemento da ricordare. Per ricordare, ripercorri mentalmente la strada e ritrovi gli oggetti.",
ap:["La memoria per i luoghi è molto forte, molto più di quella per parole astratte. Il metodo la sfrutta trasformando le informazioni in immagini collocate in uno spazio. Più le immagini sono strane, esagerate e coinvolgono i sensi, più si ricordano. I campioni di memoria lo usano per ricordare centinaia di numeri o carte.","Puoi usarlo per una lista della spesa, i punti di un discorso, i passaggi di una procedura. Con la pratica, puoi creare più percorsi per argomenti diversi."],
ri:[["Liste da ricordare","Spesa, compiti, nomi."],["Discorsi senza appunti","Devi ricordare l'ordine degli argomenti."],["Informazioni astratte","Sono difficili da trattenere."]],
es:[["Casa","Per la spesa immagini una bottiglia di latte gigante che blocca la porta, uova sul divano, un pane che fuma in cucina. Al supermercato ripercorri la casa."],["Lavoro","Per una presentazione, colleghi ogni punto a una stanza del tuo ufficio. Parli senza leggere."]],
ex:["Scegli un percorso di dieci punti in casa tua e scrivili in ordine.","Usa il percorso per memorizzare una lista di dieci oggetti e verifica dopo un'ora.","Prepara un breve discorso con tre punti collocati in tre luoghi."],
q:["Quale percorso conosco abbastanza bene?","Come rendo l'immagine più strana e vivida?","In che ordine disporrò gli elementi?"],
er:"Usare immagini troppo banali che non si fissano nella memoria.",
qz:[["Su cosa si basa il metodo dei loci?",["Ripetere ad alta voce","Collocare immagini vivide lungo un percorso conosciuto","Scrivere tutto","Leggere velocemente"],1,"Sfrutta la memoria per i luoghi."],["Quali immagini funzionano meglio?",["Banali e piccole","Strane, esagerate e vivide","Solo parole scritte","Grigie"],1,"Le immagini insolite si ricordano di più."]]},

{t:"Il prodotto minimo utile a imparare",c:"lav",tg:"La versione più piccola di un'idea che permette di imparare qualcosa dalle persone reali.",d:2,
sp:"Il prodotto minimo funzionante, o MVP, è la versione più semplice di un prodotto che ti permette di raccogliere informazioni vere da persone reali con il minimo sforzo. Non è la versione finale ridotta, è un esperimento. Può essere una pagina web che descrive un servizio non ancora esistente, un prototipo di cartone o un servizio fatto a mano.",
ap:["Un esempio citato spesso è Dropbox: prima di costruire tutto, il fondatore pubblicò un video che mostrava come avrebbe funzionato. Le iscrizioni alla lista d'attesa crebbero enormemente, confermando l'interesse. Un altro esempio è vendere un prodotto prima di produrlo per vedere se qualcuno lo compra.","La parola chiave è imparare: prima di costruire il MVP, chiarisci cosa vuoi scoprire. Un buon MVP è minimo nello sforzo ma sufficiente a dare una risposta chiara. Se nessuno lo prova, non hai imparato nulla."],
ri:[["Progetti perfetti mai lanciati","Aspetti che sia tutto pronto."],["Domande senza risposta","Non sai se l'idea interessa."],["Investimenti grandi su ipotesi","Spendi prima di sapere."]],
es:[["Lavoro","Prima di aprire un laboratorio di ceramica, un artigiano organizza tre lezioni in un locale in prestito. Scopre che il pubblico è fatto di coppie e adatta l'offerta."],["Te stesso","Prima di scrivere un libro di ricette, pubblichi dieci ricette su un blog e vedi quali interessano."]],
ex:["Per una tua idea, scrivi in una frase cosa vuoi imparare.","Progetta la versione più piccola che ti dia una risposta e realizzala in una settimana.","Fissa un criterio: quante persone devono reagire per considerarlo un successo?"],
q:["Cosa voglio imparare con questo esperimento?","Qual è la versione più piccola che mi dà la risposta?","Cosa mi diranno le reazioni delle persone reali?"],
er:"Costruire un MVP senza sapere cosa si vuole imparare.",
qz:[["Qual è lo scopo principale di un MVP?",["Vendere tanto","Imparare dalle persone reali con il minimo sforzo","Essere perfetto","Impressionare gli investitori"],1,"È un esperimento per imparare."],["Quale può essere un MVP?",["Il prodotto finale completo","Una pagina che descrive un servizio per vedere chi si iscrive","Un piano di cento pagine","Una riunione"],1,"Raccoglie dati veri con poco sforzo."]]},

{t:"La piramide di Minto e SCQA",c:"com",tg:"Parti dalla conclusione, poi dai le ragioni: Situazione, Complicazione, Domanda, Risposta.",d:2,
sp:"Barbara Minto, consulente di McKinsey, ha insegnato a scrivere in modo chiaro partendo dalla conclusione. Il messaggio principale sta in cima alla piramide, sotto ci sono le ragioni che lo sostengono, e sotto ancora i dati. Per introdurre il messaggio si usa lo schema SCQA: Situazione (il contesto noto), Complicazione (cosa è cambiato), Domanda (che problema nasce) e Risposta (la tua conclusione).",
ap:["Chi legge è impegnato: se la conclusione arriva alla fine, rischia di non arrivarci. Partire dalla risposta permette a chi ha fretta di capire subito e a chi vuole approfondire di seguire le ragioni. Le ragioni allo stesso livello devono essere ordinate e non sovrapporsi.","Esempio SCQA: «Il nostro negozio vende bene da anni (S). Da sei mesi un concorrente online offre prezzi più bassi (C). Come manteniamo i clienti? (Q). Proponiamo un servizio di consegna in giornata (A)». Funziona per email, relazioni e presentazioni."],
ri:[["Email lunghissime","Il punto arriva in fondo."],["Lettori confusi","Non capiscono cosa chiedi."],["Presentazioni senza filo","I dati arrivano prima del messaggio."]],
es:[["Lavoro","Riscrivi una mail al capo iniziando con «Propongo di posticipare il lancio di due settimane», seguita da tre ragioni. Ottieni risposta in un'ora."],["Famiglia","Per convincere la famiglia a cambiare vacanza usi SCQA: «Andiamo sempre al mare, quest'anno i prezzi sono raddoppiati, cosa facciamo? Propongo la montagna»."]],
ex:["Riscrivi una tua email recente mettendo la conclusione nella prima riga.","Prepara un messaggio importante con lo schema SCQA.","Controlla che le ragioni a sostegno non si sovrappongano."],
q:["Qual è il mio messaggio principale in una frase?","Quali ragioni lo sostengono?","Come introduco il tema con situazione, complicazione e domanda?"],
er:"Mettere la conclusione all'inizio senza ragioni solide che la sostengano.",
qz:[["Cosa sta in cima alla piramide di Minto?",["I dati","Il messaggio principale o conclusione","Le domande","I ringraziamenti"],1,"Si parte dalla conclusione."],["Cosa significa la C di SCQA?",["Conclusione","Complicazione","Contesto","Costo"],1,"Indica cosa è cambiato nella situazione."]]},

{t:"La legge di Moore",c:"sis",tg:"La potenza dei computer è raddoppiata a intervalli regolari: le tecnologie esponenziali cambiano tutto in fretta.",d:2,
sp:"Nel 1965 Gordon Moore, cofondatore di Intel, osservò che il numero di componenti nei chip raddoppiava circa ogni anno, poi rivisto a ogni due anni. Per decenni la previsione si è rivelata corretta: i computer sono diventati sempre più potenti ed economici. Come modello mentale, ricorda che le tecnologie a crescita esponenziale cambiano il mondo più velocemente di quanto immaginiamo.",
ap:["La crescita esponenziale inganna: all'inizio sembra lenta, poi esplode. Un telefono di oggi è più potente dei computer che portarono l'uomo sulla Luna. Negli ultimi anni la legge di Moore sta rallentando per limiti fisici, ma lo stesso schema si vede in altri campi, come il costo dell'energia solare o della lettura del DNA.","Per usarlo, chiediti quali tecnologie stanno migliorando in modo esponenziale nel tuo campo e cosa diventerà possibile tra cinque anni. Non pianificare guardando solo cosa è possibile oggi."],
ri:[["Tecnologia che migliora velocemente","Ogni anno costa meno e fa di più."],["Previsioni sottovalutate","Pensavi che servisse molto più tempo."],["Competenze che invecchiano in fretta","Ciò che sapevi non basta più."]],
es:[["Lavoro","Un fotografo nota che le fotocamere dei telefoni migliorano ogni anno. Si sposta verso servizi che la tecnologia non sostituisce: ritratti in studio e corsi."],["Te stesso","Invece di comprare un dispositivo costosissimo oggi, compri ciò che ti serve: tra due anni lo stesso costerà molto meno."]],
ex:["Scegli una tecnologia del tuo campo e cerca quanto costava o faceva dieci anni fa rispetto a oggi.","Immagina cosa sarà possibile nel tuo lavoro tra cinque anni se il miglioramento continua.","Individua una competenza che la tecnologia renderà meno preziosa e una che diventerà più preziosa."],
q:["Quali tecnologie stanno migliorando in modo esponenziale?","Cosa sarà possibile tra cinque anni?","Sto pianificando guardando solo il presente?"],
er:"Pensare che ogni tecnologia cresca per sempre allo stesso ritmo.",
qz:[["Cosa osservò Gordon Moore?",["I computer diventano più costosi","Il numero di componenti nei chip raddoppiava a intervalli regolari","Internet è lento","I chip non cambiano"],1,"Una crescita esponenziale della potenza."],["Perché la crescita esponenziale inganna?",["Perché è lineare","Perché all'inizio sembra lenta e poi esplode","Perché non esiste","Perché si ferma subito"],1,"Il nostro intuito ragiona in modo lineare."]]},

{t:"Il metodo MoSCoW",c:"lav",tg:"Dividi le richieste in: da fare, da fare se possibile, utili, non questa volta.",d:1,
sp:"Il metodo MoSCoW, ideato da Dai Clegg, aiuta a stabilire le priorità quando tempo e risorse sono limitati. Ogni richiesta viene classificata in quattro gruppi: Must (indispensabile, senza non funziona), Should (importante ma non vitale), Could (bello da avere se avanza tempo) e Won't (non questa volta). Il nome viene dalle iniziali inglesi.",
ap:["Il metodo funziona perché obbliga a dire esplicitamente cosa non si farà, invece di promettere tutto. La regola pratica è che i «Must» non dovrebbero superare circa il 60% dello sforzo disponibile, così resta spazio per gli imprevisti.","Puoi usarlo per un progetto di lavoro, l'organizzazione di un evento, un trasloco o una vacanza. È utile soprattutto quando più persone hanno richieste diverse e bisogna metterle d'accordo."],
ri:[["Tutto è prioritario","Ogni richiesta sembra indispensabile."],["Progetti che sforano","Scadenze e budget superati."],["Persone con richieste diverse","Bisogna mettere d'accordo molti."]],
es:[["Famiglia","Per un trasloco: Must, letti e cucina pronti il primo giorno; Should, armadi; Could, quadri appesi; Won't, ridipingere."],["Lavoro","Per il nuovo sito, il gruppo decide che il carrello è Must, le recensioni Should, la chat Could, l'app mobile Won't per ora."]],
ex:["Per un progetto in corso, scrivi tutte le richieste e classificale con MoSCoW.","Verifica che i Must non superino il 60% del tempo disponibile.","Comunica chiaramente cosa è stato messo in «non questa volta»."],
q:["Senza cosa il progetto non funziona?","Cosa posso rimandare senza danni?","Ho detto chiaramente cosa non farò?"],
er:"Mettere quasi tutto nei Must, svuotando il senso del metodo.",
qz:[["Cosa indica la categoria Won't?",["Ciò che non piace","Ciò che non si farà questa volta","Ciò che è vietato","Ciò che è indispensabile"],1,"Rende esplicite le rinunce."],["Qual è un rischio del metodo?",["Fare troppo poco","Mettere troppe cose tra i Must","Ignorare i clienti","Nessuno"],1,"Se tutto è indispensabile, nulla lo è."]]},

{t:"Il reticolo di Munger",c:"rag",tg:"Collega modelli di discipline diverse in una rete per pensare meglio.",d:2,
sp:"Charlie Munger, socio di Warren Buffett, sosteneva che per decidere bene non basta conoscere la propria materia. Serve un reticolo di modelli mentali presi da molte discipline (psicologia, economia, fisica, biologia, matematica) e collegati tra loro. Chi ha un solo modello vede ogni problema nello stesso modo; chi ha un reticolo vede più cause e più soluzioni.",
ap:["Munger diceva che a chi ha solo un martello ogni problema sembra un chiodo. Il suo consiglio era imparare le grandi idee delle principali discipline e appenderle a un reticolo mentale, collegandole all'esperienza. Alcuni dei modelli più potenti emergono quando più forze agiscono insieme: ad esempio incentivi, prova sociale e scarsità che si rinforzano a vicenda.","Questa app è costruita proprio così: modelli da aree diverse da collegare tra loro. Per usarli come reticolo, davanti a un problema chiediti quali modelli si applicano e come interagiscono."],
ri:[["Spiegazione unica per tutto","Usi sempre la stessa lente."],["Esperti di un solo campo","Vedi solo il tuo settore."],["Più forze che si sommano","Diversi fattori spingono nella stessa direzione."]],
es:[["Soldi","Per capire una bolla speculativa, combini prova sociale (lo fanno tutti), incentivi (chi vende guadagna) e crescita composta del debito."],["Lavoro","Per capire perché un progetto è fallito, usi colli di bottiglia, incentivi e il cerchio di competenza. Ognuno spiega una parte."]],
ex:["Prendi un problema e applica almeno un modello da tre aree diverse di questa app.","Cerca due modelli che, insieme, spiegano un fenomeno meglio di uno solo.","Scegli un'area dove hai pochi modelli e studiane uno questa settimana."],
q:["Quali modelli di aree diverse si applicano qui?","Come interagiscono tra loro?","Sto usando sempre la stessa lente?"],
er:"Conoscere molti modelli senza collegarli tra loro e all'esperienza.",
qz:[["Cosa intendeva Munger con «reticolo di modelli mentali»?",["Una rete internet","Un insieme collegato di modelli da molte discipline","Un libro","Un gruppo di amici"],1,"I modelli vanno collegati tra loro."],["Cosa significa «a chi ha solo un martello ogni problema sembra un chiodo»?",["I martelli sono utili","Chi conosce un solo modello lo applica a tutto","I chiodi sono problemi","Serve più ferramenta"],1,"Serve varietà di strumenti mentali."]]},

{t:"Il processo di progettazione in cinque passi",c:"lav",tg:"Obiettivi chiari, problemi riconosciuti, cause diagnosticate, piano, esecuzione.",d:2,
sp:"Ray Dalio, fondatore di un grande fondo d'investimento, descrive un processo in cinque passi per ottenere ciò che vuoi nella vita e nel lavoro: avere obiettivi chiari; individuare i problemi che ostacolano il cammino senza tollerarli; diagnosticarne le cause profonde; progettare un piano per superarli; portare a termine il piano. Il ciclo si ripete continuamente.",
ap:["Secondo Dalio molte persone saltano dei passi: fissano obiettivi ma non guardano i problemi, oppure vedono i problemi ma non ne cercano le cause, oppure fanno piani perfetti e non li eseguono. Ognuno di noi tende a essere bravo in alcuni passi e debole in altri.","Per usarlo, scrivi i cinque passi per un obiettivo e valuta onestamente in quale sei più debole. Se non sei bravo in un passo, chiedi aiuto a qualcuno che lo è: chi pianifica bene, chi esegue con costanza, chi vede i problemi."],
ri:[["Obiettivi che non avanzano","Hai buone intenzioni ma niente cambia."],["Problemi tollerati","Ti abitui a ciò che non funziona."],["Piani mai eseguiti","Progetti tutto ma non concludi."]],
es:[["Te stesso","Obiettivo: risparmiare. Problema: a fine mese non resta nulla. Causa: spese al ristorante non pianificate. Piano: budget settimanale. Esecuzione: app per tracciare le spese."],["Lavoro","Un gruppo vuole ridurre i reclami. Individua i problemi, ne cerca la causa, progetta una nuova procedura e controlla ogni settimana l'applicazione."]],
ex:["Scegli un obiettivo e scrivi i cinque passi in cinque righe.","Valuta da 1 a 5 quanto sei bravo in ciascun passo.","Trova una persona che possa aiutarti nel passo più debole."],
q:["Il mio obiettivo è chiaro?","Quali problemi sto tollerando, e qual è la loro causa?","Ho un piano e lo sto davvero eseguendo?"],
er:"Confondere i problemi con le loro cause.",
qz:[["Qual è il terzo passo del processo di Dalio?",["Eseguire","Diagnosticare le cause profonde dei problemi","Fissare gli obiettivi","Festeggiare"],1,"Va capita la causa prima di progettare."],["Cosa fare se sei debole in uno dei passi?",["Saltarlo","Chiedere aiuto a qualcuno bravo in quel passo","Rinunciare","Ripetere gli altri"],1,"Gli altri possono compensare le tue debolezze."]]},

{t:"Distruzione reciproca assicurata",c:"eco",tg:"Quando un attacco garantirebbe la distruzione di entrambi, a nessuno conviene attaccare.",d:3,
sp:"Durante la Guerra Fredda, Stati Uniti e Unione Sovietica avevano abbastanza armi nucleari da distruggersi a vicenda anche dopo un primo attacco. Questa situazione, chiamata distruzione reciproca assicurata, rendeva irrazionale attaccare per primi. Come modello mentale, descrive le situazioni in cui due parti hanno entrambe il potere di danneggiarsi gravemente e per questo si trattengono.",
ap:["La deterrenza funziona se ciascuna parte è convinta che l'altra possa e voglia reagire, e se entrambe agiscono in modo razionale. Ma è un equilibrio fragile: un errore, un malinteso o un attore irrazionale possono portare al disastro. Durante la Guerra Fredda ci furono diversi falsi allarmi pericolosi.","Situazioni simili esistono anche nella vita: due aziende che potrebbero farsi causa a vicenda, due colleghi che conoscono i segreti dell'altro, una guerra dei prezzi che danneggerebbe entrambi. Il modello aiuta a capire perché c'è una calma tesa, ma ricorda che è meglio costruire fiducia che vivere sulla minaccia."],
ri:[["Calma tesa","Nessuno attacca, ma la tensione resta."],["Potere di danno reciproco","Entrambi possono farsi molto male."],["Escalation possibile","Un piccolo errore potrebbe scatenare tutto."]],
es:[["Lavoro","Due negozi vicini potrebbero iniziare una guerra dei prezzi che rovinerebbe entrambi. Nessuno inizia, e col tempo si specializzano su prodotti diversi."],["Relazioni","In una lite familiare entrambi conoscono le ferite dell'altro. Capendo che colpire porterebbe danni a entrambi, decidete di parlare con calma."]],
ex:["Pensa a una situazione in cui tu e un'altra parte potreste farvi molto male a vicenda. Cosa vi trattiene?","Individua un modo per passare dalla minaccia alla fiducia in quella relazione.","Ripensa a un conflitto che si è aggravato: c'è stato un malinteso che ha fatto saltare l'equilibrio?"],
q:["Entrambi possiamo farci molto male?","Cosa trattiene ciascuno dall'attaccare?","Come posso ridurre il rischio di un errore o di un malinteso?"],
er:"Considerare stabile un equilibrio basato solo sulla paura.",
qz:[["Perché la distruzione reciproca assicurata scoraggiava gli attacchi?",["Le armi erano poche","Un attacco avrebbe garantito la distruzione di entrambi","C'era un trattato","Nessuno aveva armi"],1,"Attaccare sarebbe stato un suicidio."],["Qual è un punto debole di questo equilibrio?",["È troppo stabile","Errori, malintesi o attori irrazionali possono farlo saltare","Non ha punti deboli","Costa poco"],1,"Si regge sulla razionalità di tutti."]]},

{t:"Comunicazione nonviolenta",c:"com",tg:"Osservazione, sentimento, bisogno, richiesta: parla in modo che l'altro possa ascoltare.",d:2,
sp:"Lo psicologo Marshall Rosenberg ha proposto un modo di comunicare in quattro passi: descrivere un fatto osservabile senza giudicare, esprimere il sentimento che provi, indicare il bisogno che sta dietro al sentimento e fare una richiesta concreta. Al posto di «sei sempre in ritardo, non ti importa di me» si dice: «Quando arrivi mezz'ora dopo l'orario, mi sento frustrato perché ho bisogno di poter organizzare la serata. Puoi avvisarmi se tardi?».",
ap:["I giudizi e le accuse fanno scattare la difesa: l'altro si concentra sul rispondere, non sul capire. Descrivere fatti, sentimenti e bisogni rende più facile ascoltare e trovare una soluzione. Lo stesso metodo vale per ascoltare: cerca il sentimento e il bisogno dietro le parole dure dell'altro.","Una richiesta è diversa da una pretesa: deve essere concreta, possibile e lasciare libero l'altro di dire no. Il metodo all'inizio sembra artificiale; con la pratica diventa più naturale."],
ri:[["Accuse e generalizzazioni","«Sempre», «mai», «sei il solito»."],["Discussioni che degenerano","Ogni frase alza la tensione."],["Bisogni non detti","Ti arrabbi senza dire cosa ti serve."]],
es:[["Famiglia","Invece di «la tua camera è un porcile», dici: «Vedo vestiti sul pavimento e mi sento a disagio perché ho bisogno di ordine in casa. Puoi metterli a posto prima di cena?»."],["Lavoro","Con un collega: «Quando ricevo il report il giorno della scadenza mi sento sotto pressione perché ho bisogno di tempo per controllarlo. Puoi mandarmelo un giorno prima?»."]],
ex:["Riscrivi una critica che vorresti fare usando i quattro passi.","Nella prossima discussione, prova a indovinare il bisogno dietro le parole dell'altro.","Trasforma una tua pretesa in una richiesta concreta che lascia libero l'altro."],
q:["Cosa ho osservato, senza giudizio?","Cosa provo, e di cosa ho bisogno?","Quale richiesta concreta posso fare?"],
er:"Usare la formula in modo meccanico, mascherando un'accusa da osservazione.",
qz:[["Qual è il primo passo della comunicazione nonviolenta?",["Esprimere un giudizio","Descrivere un fatto osservabile","Fare una richiesta","Alzare la voce"],1,"Si parte da fatti, non da giudizi."],["Cosa distingue una richiesta da una pretesa?",["Il tono","La richiesta lascia libero l'altro di dire no","La lunghezza","Nulla"],1,"Una richiesta accetta anche un rifiuto."]]},

{t:"Il ciclo OODA",c:"rag",tg:"Osserva, orientati, decidi, agisci, e ricomincia più velocemente degli altri.",d:2,
sp:"Il colonnello dell'aviazione americana John Boyd ha descritto il ciclo OODA: Osservare cosa succede, Orientarsi interpretando le informazioni alla luce di esperienza e contesto, Decidere cosa fare e Agire. Poi si ricomincia, osservando gli effetti. Chi completa il ciclo più velocemente e con più precisione dell'avversario ha un vantaggio decisivo, in un combattimento aereo come in un mercato.",
ap:["Boyd considerava l'orientamento la fase più importante: è lì che la nostra cultura, le esperienze e i modelli mentali filtrano ciò che vediamo. Un orientamento sbagliato fa decidere male anche con buone informazioni. Per questo serve aggiornare continuamente il proprio modo di interpretare il mondo.","Il ciclo è utile in situazioni che cambiano in fretta: emergenze, trattative, competizione, sport. Non serve un piano perfetto, serve un ciclo rapido di osservazione e correzione."],
ri:[["Situazione che cambia in fretta","Il piano invecchia mentre lo scrivi."],["Decisioni lente","Gli altri si muovono prima di te."],["Interpretazioni rigide","Leggi i fatti nuovi con schemi vecchi."]],
es:[["Lavoro","Un negozio online osserva un calo di visite, si orienta scoprendo che un concorrente ha lanciato una promozione, decide di rispondere con la consegna gratuita, agisce in un giorno e osserva i risultati."],["Sport","Un tennista osserva che l'avversario è debole sul rovescio, si orienta, decide di giocare lì e agisce. Quando l'altro si adatta, ricomincia il ciclo."]],
ex:["Applica i quattro passi a una situazione in rapido cambiamento che stai vivendo.","Chiediti quale esperienza o convinzione sta influenzando il tuo orientamento.","Riduci i tempi di un ciclo decisionale ricorrente (ad esempio una revisione settimanale invece che mensile)."],
q:["Cosa sta succedendo davvero?","Come sto interpretando i fatti, e con quali filtri?","Qual è la decisione più rapida e correggibile che posso prendere?"],
er:"Velocizzare il ciclo saltando l'orientamento.",
qz:[["Quale fase del ciclo OODA Boyd considerava più importante?",["Osservare","Orientarsi","Decidere","Agire"],1,"L'orientamento filtra tutto ciò che vediamo."],["Cosa dà un vantaggio secondo il modello?",["Un piano perfetto","Completare il ciclo più velocemente e con precisione","Agire senza osservare","Aspettare"],1,"Adattarsi più in fretta degli altri."]]},

{t:"La finestra di Overton",c:"com",tg:"L'insieme delle idee considerate accettabili in un certo momento può spostarsi.",d:2,
sp:"La finestra di Overton, dal nome del ricercatore Joseph Overton, descrive l'insieme delle idee politiche considerate accettabili dal pubblico in un dato momento. Le idee fuori dalla finestra sembrano impensabili o estreme; quelle dentro sono discutibili o normali. La finestra non è fissa: si sposta nel tempo, a volte lentamente, a volte in fretta.",
ap:["Idee un tempo impensabili, come il voto alle donne o il divieto di fumo nei locali, sono diventate normali. La finestra si sposta con eventi, movimenti sociali, media e anche con chi propone idee estreme che rendono più accettabili quelle intermedie.","Il modello aiuta a capire perché alcune proposte vengono ignorate e altre diventano popolari, e come opinioni pubbliche possono essere spostate in modo consapevole. Vale anche in piccolo: in un'azienda o in una famiglia ci sono idee che «non si possono dire»."],
ri:[["Idee impensabili che diventano normali","Ciò che ieri era scandaloso oggi si discute."],["Proposte estreme","Rendono più accettabili quelle intermedie."],["Temi tabù","In un gruppo certe idee non si possono dire."]],
es:[["Società","Lavorare da casa era un'idea marginale per molte aziende. Dopo la pandemia è entrata nella finestra delle opzioni normali."],["Lavoro","In un ufficio proporre la settimana di quattro giorni sembra impensabile. Una collega propone prima i venerdì pomeriggio liberi d'estate."]],
ex:["Pensa a un'idea oggi normale che vent'anni fa era impensabile. Cosa l'ha spostata?","Individua un tema tabù nel tuo gruppo di lavoro o famiglia.","Se vuoi proporre un cambiamento grande, scrivi un primo passo che stia dentro la finestra attuale."],
q:["Questa idea è dentro o fuori la finestra di ciò che è accettabile?","Cosa potrebbe spostare la finestra?","Qualcuno sta spostando la finestra in modo consapevole?"],
er:"Pensare che ciò che è accettabile oggi lo sia per natura e per sempre.",
qz:[["Cosa descrive la finestra di Overton?",["Una finestra di casa","L'insieme delle idee considerate accettabili in un certo momento","Un programma informatico","Un tipo di sondaggio"],1,"Delimita ciò che si può discutere pubblicamente."],["Come si può spostare la finestra?",["Non si può","Con eventi, movimenti, media e proposte che cambiano i confini","Solo per legge","Con il caso"],1,"La finestra è dinamica."]]}
);
